export const HEIC_SOURCE = { single: { w: 96, h: 64 }, grid: { w: 128, h: 128, tile: 64 } };
const be32 = (n: number) => { const b = Buffer.alloc(4); b.writeUInt32BE(n >>> 0); return b; }, be16 = (n: number) => { const b = Buffer.alloc(2); b.writeUInt16BE(n); return b; };
