  const r = spawnSync('ffmpeg', ['-v', 'error', '-f', 'lavfi', '-i', `testsrc2=size=${size}:rate=1:duration=1`, '-frames:v', '1', ...vf, '-pix_fmt', 'yuv420p', '-c:v', 'libx265', '-x265-params', 'log-level=error:keyint=1', '-f', 'hevc', '-'], { maxBuffer: 16 << 20 });
